import java.util.*;class Solution{int f(int[]p,int x){return p[x]==x?x:(p[x]=f(p,p[x]));}public List<Integer> numIslands2(int m,int n,int[][]pos){int[]p=new int[m*n];Arrays.fill(p,-1);List<Integer>o=new ArrayList<>();int c=0;int[][]d={{1,0},{-1,0},{0,1},{0,-1}};for(int[]v:pos){int r=v[0],q=v[1],id=r*n+q;if(p[id]!=-1){o.add(c);continue;}p[id]=id;c++;for(int[]z:d){int a=r+z[0],b=q+z[1];if(a<0||b<0||a>=m||b>=n||p[a*n+b]==-1)continue;int x=f(p,id),y=f(p,a*n+b);if(x!=y){p[x]=y;c--;}}o.add(c);}return o;}}
